import type { PlayerProgression } from './types';

export const MAX_PLAYER_LEVEL = 50;

export function xpForLevel(level: number): number {
  const n = Math.max(0, Math.min(49, Math.floor(level) - 1));
  return 100 * n * n + 400 * n;
}

export const MAX_PLAYER_XP = xpForLevel(MAX_PLAYER_LEVEL);

export function levelForXp(xp: number): number {
  const x = Math.max(0, Math.min(MAX_PLAYER_XP, Math.floor(xp)));
  let level = 1;
  while (level < MAX_PLAYER_LEVEL && xpForLevel(level + 1) <= x) {
    level++;
  }
  return level;
}

export function createProgression(xp = 0): PlayerProgression {
  const value = Math.max(0, Math.min(MAX_PLAYER_XP, Math.floor(xp)));
  return { xp: value, level: levelForXp(value) };
}

export function addXp(p: PlayerProgression, amount: number): PlayerProgression {
  return createProgression(p.xp + (Number.isFinite(amount) ? Math.max(0, amount) : 0));
}
